    settings_ai_icon_label: "AI Assistant Icon", settings_ai_fab_compact_label: "Make the AI assistant button smaller",
    theme_category_toys: "Toys & Games", theme_category_design: "Architecture & Design", theme_category_space: "Space & Astronomy", theme_category_retro: "Retro & Digital", theme_category_finance: "Finance & Markets", theme_category_industrial: "Industrial & Vintage", theme_category_art: "Art & Illustration", theme_category_nature: "Science & Nature", theme_category_kids: "Kids' Art", theme_category_transport: "Moving Things", theme_special_section_label: "Special Themes",
    settings_text_color_label: "Text Color", settings_font_label: "Font (Premium)", font_picker_default_option: "Default", font_search_placeholder: "Search font...", settings_accessibility_label: "Color & Contrast Accessibility", settings_high_contrast_label: "High Contrast Mode", settings_color_filter_label: "Color Filter", color_filter_none: "None", color_filter_grayscale: "Grayscale",
