    habit_history_stat_current: "Obecna seria", habit_history_stat_best: "Najlepsza seria", habit_history_stat_total: "Łącznie dni", habits_empty_hint: "Nie masz jeszcze żadnych nawyków - dodaj jeden, aby zacząć śledzić swoją serię.", habits_add_modal_title: "Nowy nawyk", habits_name_placeholder: "np. Pić wodę, Czytać, Medytować...", habits_missing_name: "Podaj nazwę nawyku", habits_delete_title: "Usunąć ten nawyk?", habits_delete_confirm: "Spowoduje to również trwałe usunięcie całej jego historii i serii.", habits_link_sport_label: "Zapisz to też jako sesję sportową po ukończeniu", habits_sport_duration_placeholder: "Czas trwania w minutach", habits_missing_sport_duration: "Podaj czas trwania w minutach", habit_auto_logged_sport_badge: "Z nawyku", habits_overview_btn_title: "Podgląd miesięczny", habits_overview_title: "Nawyki - Podgląd miesięczny", routine_goals_section_title: "🎯 Cele i Nawyki", routine_goals_empty_hint: "W tej zakładce nic jeszcze nie ma - dodaj elementy do swojej rutyny, aby śledzić je tutaj.", routine_goals_toggle_label: "Pokaż śledzenie celów i nawyków",
