    settings_contact_us_btn: "📬 ہم سے رابطہ کریں",
    contact_us_category_bug: "🐛 خرابی کی اطلاع دیں", contact_us_category_feature: "💡 فیچر تجویز کریں", contact_us_category_help: "❓ ایپ استعمال کرنے میں مدد", contact_us_category_other: "💬 دیگر",
