    nb_shelf_empty: "Zatím tu nejsou žádné sešity",
    nb_premium_text: "Kapsa pro každou oblast života, sešity s listujícími stránkami a vlastní tabulky – součást Premium.",
    nb_premium_title: "Kapsy, sešity a tabulky",
    nb_tasks_notebook_title: "Úkoly",
