    auth_forgot_password_link: "Unohditko salasanan?", auth_back_to_login: "Takaisin kirjautumiseen", auth_forgot_subtitle: "Anna sähköpostiosoitteesi, niin lähetämme sinulle palautuslinkin:", auth_forgot_submit_btn: "Lähetä palautuslinkki", auth_fill_email: "Anna sähköpostiosoitteesi", auth_forgot_success: "Jos tämä sähköposti on olemassa, palautuslinkki on matkalla - tarkista postilaatikkosi.",
